layer.css:
@import url("https://fonts.googleapis.com/css2?family=Merriweather:ital,wght@0,400;0,500;0,700;1,400&family=Inter:wght@400;500;600&family=IBM+Plex+Mono:wght@400&display=swap");
[data-ryt="pitch"] { color: rgb(107, 101, 96); border-left: 3px solid rgb(139, 69, 19); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 18px; font-weight: 400; font-style: italic; line-height: 1.75; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(107, 101, 96); text-decoration-thickness: auto; text-underline-offset: auto; padding-top: 9px; padding-right: 36px; padding-bottom: 9px; padding-left: 36px; transition: all; border-top: none; border-right: none; border-bottom: none }
[data-ryt="footer"] { color: var(--ryt-text); border-top: 1px solid rgb(221, 216, 208); font-style: normal; letter-spacing: normal; text-transform: none }
article[data-ryt="rec-card"] { border-bottom: 1px solid rgb(221, 216, 208); border-radius: 0px; transition: all; border-top: none; border-right: none; border-left: none }
[data-ryt="credit"] a, [data-ryt="review"] a, [data-ryt="bio"] a { color: var(--ryt-accent); border-radius: 0px; font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-line: underline; text-decoration-style: solid; text-decoration-color: rgb(221, 216, 208); text-decoration-thickness: auto; text-underline-offset: 3px; transition: color 0.15s, text-decoration-color 0.15s }
[data-ryt="section"] > h2 { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 600; font-style: normal; line-height: 1.25; letter-spacing: -0.54px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: auto; transition: all }
[data-ryt="brand"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 19.8px; font-weight: 600; font-style: normal; line-height: 1.75; letter-spacing: 0.792px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3px; transition: color 0.15s, text-decoration-color 0.15s }
[data-ryt="header"] { border-bottom: 1px solid rgb(221, 216, 208); border-top: none }
[data-ryt="nav"] a { color: rgb(107, 101, 96); border-radius: 0px; font-family: Inter, "Helvetica Neue", Arial, sans-serif; font-size: 14.4px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: 1.152px; text-transform: uppercase; text-decoration-style: solid; text-decoration-color: rgb(107, 101, 96); text-decoration-thickness: auto; text-underline-offset: 3px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: color 0.15s }
[data-ryt="review"] { color: rgb(107, 101, 96); font-family: var(--ryt-font-heading); font-size: 17.1px; font-weight: 400; font-style: normal; line-height: 1.6; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(107, 101, 96); text-decoration-thickness: auto; text-underline-offset: 3px; transition: all }
[data-ryt="credit"], [data-ryt="eyebrow"] { color: #908b86; font-family: "IBM Plex Mono", "JetBrains Mono", "Courier New", monospace; font-size: 13.5px; font-weight: 400; font-style: normal; line-height: 1.75; letter-spacing: 0.27px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(155, 149, 144); text-decoration-thickness: auto; text-underline-offset: 3px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"] a { color: var(--ryt-text); border-left: 3px solid rgb(139, 69, 19); border-radius: 0px; font-family: var(--ryt-font-heading); font-weight: 400; font-style: normal; letter-spacing: normal; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3px; transition: 0.15s; border-top: none; border-right: none; border-bottom: none }
[data-ryt="rec-card"] [data-ryt="title"] { color: var(--ryt-text); border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24.3px; font-weight: 600; font-style: normal; line-height: 1.3; letter-spacing: -0.3645px; text-transform: none; text-decoration-style: solid; text-decoration-color: var(--ryt-text); text-decoration-thickness: auto; text-underline-offset: 3px; transition: all }
[data-ryt="rec-card"] [data-ryt="title"]::after { content: " →"; display: inline; color: rgb(139, 69, 19); background-size: auto; background-position: 0% 0%; background-repeat: repeat; border-radius: 0px; font-family: var(--ryt-font-heading); font-size: 24.3px; font-weight: 600; font-style: normal; line-height: 1.3; letter-spacing: -0.3645px; text-transform: none; text-decoration-style: solid; text-decoration-color: rgb(139, 69, 19); text-decoration-thickness: auto; text-underline-offset: 3px; padding-top: 0px; padding-right: 0px; padding-bottom: 0px; padding-left: 0px; transition: opacity 0.15s; -webkit-text-fill-color: rgb(139, 69, 19) }
[data-ryt="rec-card"] [data-ryt="title"]:hover { color: #8B4513 }
[data-ryt="rec-card"] [data-ryt="title"] a:hover { color: #8B4513; text-decoration-color: #8B4513; border-left-color: #8B4513; background-color: #EDE9E3 }
[data-ryt="nav"] a:hover { color: #8B4513; text-decoration-color: #8B4513; color: #2C2C2C }
[data-ryt="brand"]:hover { color: #8B4513; text-decoration-color: #8B4513; color: #8B4513; text-decoration-line: none; text-decoration-thickness: initial; text-decoration-style: initial; text-decoration-color: initial }
[data-ryt="credit"] a:hover, [data-ryt="review"] a:hover, [data-ryt="bio"] a:hover { color: #8B4513; text-decoration-color: #8B4513 }
